/** The packed boundary transports existing occurrence provenance without observing caller RDF values. */
class PackedApiInputOriginTest {

	@Test
	void scalarRoundTripPreservesApiOriginWithoutLexicalObservation() {
		var value = new ObservedBNode();
		TupleExpr source = scalar(value);
		TupleExpr output = roundTrip(source);
		Var variable = variables(output).getFirst();
		assertTrue(variable.hasApiInputOrigin(), "the caller-binding role survives packed materialization");
		assertSame(value, variable.getValue());
		assertEquals(0, value.lexicalReads.get(), "encoding and materialization do not use the RDF value");
		var references = LocalBNodeReferences.analyze(output);
		assertEquals(1, references.runtimeValues().size());
		assertSame(value, references.runtimeValues().getFirst());
		assertTrue(references.ids().isEmpty(), "runtime inputs do not become syntactic local blank-node IDs");
		assertEquals(0, value.lexicalReads.get(), "the real post-optimization analysis preserves deferred input");
	}

	@Test
	void equalNamedAndValuedOccurrencesKeepDifferentOriginRoles() {
		var value = SimpleValueFactory.getInstance().createBNode("ordinary-and-input");
		Var input = Var.of("provided", value).withApiInputOrigin();
		Var ordinary = Var.of("provided", value);
		TupleExpr source = new Extension(new SingletonSet(), new ExtensionElem(input, "input"),
				new ExtensionElem(ordinary, "ordinary"));
		List<Var> output = variables(roundTrip(source));
		assertEquals(2, output.size());
		assertTrue(output.get(0).hasApiInputOrigin());
		assertFalse(output.get(1).hasApiInputOrigin(), "a sibling input does not promote a syntactic occurrence");
		assertSame(value, output.get(0).getValue());
		assertSame(value, output.get(1).getValue());
		var references = LocalBNodeReferences.analyze(roundTrip(source));
		assertEquals(1, references.runtimeValues().size());
		assertTrue(references.ids().contains(value.getID()), "ordinary syntax keeps its existing local-ID role");
	}

	@ParameterizedTest(name = "nested={0}")
	@ValueSource(strings = { "union", "optional", "exists", "subquery" })
	void nestedRoundTripKeepsEveryOccurrenceRole(String shape) {
		var value = new ObservedBNode();
		TupleExpr nested = switch (shape) {
		case "union" -> new Union(scalar(value), new SingletonSet());
		case "optional" -> new LeftJoin(new SingletonSet(), scalar(value));
		case "exists" -> new Filter(new SingletonSet(), new Exists(new StatementPattern(
				Var.of("provided", value).withApiInputOrigin(), Var.of("p"), Var.of("o"))));
		case "subquery" -> new Projection(scalar(value), new ProjectionElemList(new ProjectionElem("copy")));
		default -> throw new AssertionError(shape);
		};
		TupleExpr source = new QueryRoot(nested);
		List<Var> original = variables(source);
		TupleExpr output = roundTrip(source);
		List<Var> actual = variables(output);
		assertEquals(original.size(), actual.size());
		assertFalse(original.isEmpty());
		for (int index = 0; index < original.size(); index++) {
			Var expected = original.get(index);
			Var result = actual.get(index);
			assertEquals(expected.hasApiInputOrigin(), result.hasApiInputOrigin(), "origin at occurrence " + index);
			assertSame(expected.getValue(), result.getValue());
			assertEquals(expected.isAnonymous(), result.isAnonymous());
			assertEquals(expected.isConstant(), result.isConstant());
			assertEquals(expected.isBNode(), result.isBNode());
		}
		var references = LocalBNodeReferences.analyze(output);
		assertEquals(1, references.runtimeValues().size());
		assertSame(value, references.runtimeValues().getFirst());
		assertEquals(0, value.lexicalReads.get());
	}

	@Test
	void canonicalPackedIdentityDistinguishesInputAndSyntacticRoles() {
		var value = SimpleValueFactory.getInstance().createBNode("same-value-and-name");
		TupleExpr input = new Extension(new SingletonSet(),
				new ExtensionElem(Var.of("provided", value).withApiInputOrigin(), "copy"));
		TupleExpr ordinary = new Extension(new SingletonSet(), new ExtensionElem(Var.of("provided", value), "copy"));
		PackedQuery marked = PackedQueryCodec.encode(input);
		PackedQuery unmarked = PackedQueryCodec.encode(ordinary);
		assertFalse(marked.hasSameCacheIdentity(unmarked), "cache identity must include the existing execution role");
		assertTrue(marked.hasSameCacheIdentity(PackedQueryCodec.encode(input)));
	}

	private static TupleExpr scalar(ObservedBNode value) {
		return new Extension(new SingletonSet(),
				new ExtensionElem(Var.of("provided", value).withApiInputOrigin(), "copy"));
	}

	private static TupleExpr roundTrip(TupleExpr source) {
		PackedQuery query = PackedQueryCodec.encode(source);
		return PackedPlanMaterializer.materialize(query, query.rootRelId());
	}

	private static List<Var> variables(TupleExpr source) {
		List<Var> result = new ArrayList<>();
		source.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Var variable) {
				result.add(variable);
			}
		});
		return result;
	}

	private static final class ObservedBNode extends SimpleBNode {
		private static final long serialVersionUID = 1L;
		private final AtomicInteger lexicalReads = new AtomicInteger();

		private ObservedBNode() {
			super("deferred-input");
		}

		@Override
		public String getID() {
			lexicalReads.incrementAndGet();
			return super.getID();
		}
	}
}
